function profileFor(lang) {
  return {
    full_name: PROFILE.personal.full_name,
    summary: PROFILE.summary[lang],
    skills: PROFILE.skills.items.map(s => ({ name: s.name, level: s.level })),
    projects: PROFILE.projects.map(p => ({
      id: p.id, name: p.name[lang], stack: p.stack,
      bullets: p.bullets[lang].map((text, i) => ({ source_index: i, text })),
    })),
    education: PROFILE.education.map(e => `${e.title[lang]} - ${e.institution}`),
    languages: 'Spanish native, English B2',
  };
}

return $input.all().map(item => {
  const j = item.json;
  const lang = j.language === 'es' ? 'es' : 'en';
  const desc = j.description ? String(j.description).slice(0, 5000) : '(no description provided)';
  const user = [
    `LANGUAGE: ${lang === 'es' ? 'Spanish' : 'English'}`,
    `CANDIDATE PROFILE (JSON):\n${JSON.stringify(profileFor(lang))}`,
    `<job_posting>\nTitle: ${j.title}\nCompany: ${j.company}\nLocation: ${j.location ?? 'unknown'}\nDescription:\n${desc}\n</job_posting>`,
  ].join('\n\n');

  return {
    json: {
      job_id: j.id, title: j.title, company: j.company, lang, profile: PROFILE,
      body: {
        model: MODEL, temperature: 0.3,
        response_format: { type: 'json_schema', json_schema: SCHEMA },
        messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }],
      },
    },
  };
});

// Review step: checks the AI output against the profile, repairs anything invented,
// then renders the CV as HTML for Gotenberg.
const requests = $('Build tailoring request').all();
const out = [];

const nums = s => (String(s).match(/\d[\d.,]*/g) || []).map(n => n.replace(/[.,]/g, '')).filter(n => n.length);
const subset = (a, b) => a.every(x => b.includes(x));
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const L = {
  en: { summary: 'Summary', projects: 'Projects', skills: 'Technical Skills', education: 'Education', languages: 'Languages',
        langs: 'Spanish: native · English: B2 (upper intermediate)',
        groups: { analytics: 'Analytics & BI', programming: 'Programming', data_engineering: 'Data engineering', automation: 'Automation & AI', tools: 'Tools' } },
  es: { summary: 'Perfil profesional', projects: 'Proyectos', skills: 'Habilidades técnicas', education: 'Educación', languages: 'Idiomas',
        langs: 'Español: nativo · Inglés: B2 (intermedio alto)',
        groups: { analytics: 'Análisis y BI', programming: 'Programación', data_engineering: 'Ingeniería de datos', automation: 'Automatización e IA', tools: 'Herramientas' } },
};
const ES_SKILL = {
  'EDA and descriptive statistics': 'EDA y estadística descriptiva',
  'KPI design and data storytelling': 'Definición de KPIs y storytelling con datos',
  'ETL processes': 'Procesos ETL', 'Data modeling': 'Modelado de datos', 'OpenAI API': 'API de OpenAI',
};

$input.all().forEach((item, i) => {
  const req = requests[i]?.json;
  const content = item.json?.choices?.[0]?.message?.content;
  if (!req || !content) return;                       // failed call: job stays 'scored', retried next run
  let ai; try { ai = JSON.parse(content); } catch (e) { return; }

  const P = req.profile, lang = req.lang, T = L[lang];
  const checks = [];
  const profileNums = nums([P.summary[lang], ...P.projects.flatMap(p => p.bullets[lang])].join(' '));

  // Summary
  let summary = ai.summary;
  if (!summary || !subset(nums(summary), profileNums)) { summary = P.summary[lang]; checks.push('Summary replaced with the original (unverified numbers)'); }

  // Skills: only profile skills, AI order first, nothing lost
  const byName = Object.fromEntries(P.skills.items.map(s => [s.name.toLowerCase(), s]));
  const ordered = [];
  for (const n of ai.skills_order || []) {
    const s = byName[String(n).toLowerCase()];
    if (s && !ordered.includes(s)) ordered.push(s); else if (!s) checks.push(`Dropped unknown skill: ${n}`);
  }
  for (const s of P.skills.items) if (!ordered.includes(s)) ordered.push(s);

  // Projects and bullets
  const byId = Object.fromEntries(P.projects.map(p => [p.id, p]));
  const projects = [];
  for (const ap of ai.projects || []) {
    const src = byId[ap.id];
    if (!src) { checks.push(`Dropped unknown project: ${ap.id}`); continue; }
    if (projects.some(p => p.src.id === src.id)) continue;
    const srcBullets = src.bullets[lang], used = new Set(), bullets = [];
    for (const b of ap.bullets || []) {
      const orig = srcBullets[b.source_index];
      if (orig === undefined || used.has(b.source_index)) continue;
      used.add(b.source_index);
      if (b.text && subset(nums(b.text), nums(orig))) bullets.push(b.text);
      else { bullets.push(orig); checks.push(`Bullet restored to original in ${src.id}`); }
    }
    for (let k = 0; bullets.length < 2 && k < srcBullets.length; k++) {   // at least 2 bullets per project
      if (!used.has(k)) { used.add(k); bullets.push(srcBullets[k]); }
    }
    projects.push({ src, bullets: bullets.slice(0, 4) });
    if (projects.length === 4) break;
  }
  for (const src of P.projects) {                    // at least 3 projects
    if (projects.length >= 3) break;
    if (!projects.some(p => p.src.id === src.id)) projects.push({ src, bullets: src.bullets[lang].slice(0, 3) });
  }

  // Cover letter: flag, don't silently change
  const cover = String(ai.cover_letter || '').trim();
  if (!subset(nums(cover), profileNums)) checks.push('Cover letter mentions numbers not in your profile: review it');

  // ---------- HTML ----------
  const per = P.personal;
  const skillName = n => lang === 'es' ? (ES_SKILL[n] || n) : n;
  const groupOf = c => (c === 'bi' ? 'analytics' : c);
  const groups = {};
  for (const s of ordered) (groups[groupOf(s.category)] ||= []).push(skillName(s.name));
  const groupOrder = [...new Set(ordered.map(s => groupOf(s.category)))];

  const html = `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><style>
    @page { size: A4; margin: 0; }
    body { font-family: Arial, Helvetica, sans-serif; color: #1a1a1a; font-size: 10pt; line-height: 1.35; margin: 0; }
    h1 { font-size: 20pt; margin: 0 0 2px; }
    .headline { font-size: 11.5pt; font-weight: bold; color: #1f4e79; margin-bottom: 4px; }
    .contact { font-size: 9pt; color: #444; }
    .contact a { color: #1f4e79; text-decoration: none; }
    h2 { font-size: 11pt; text-transform: uppercase; letter-spacing: .5px; color: #1f4e79;
         border-bottom: 1px solid #c8d3df; padding-bottom: 2px; margin: 12px 0 5px; }
    .proj { margin-bottom: 6px; }
    .proj-title { font-weight: bold; }
    .proj-title a { color: #1a1a1a; text-decoration: none; }
    .stack { color: #555; font-size: 9pt; }
    ul { margin: 2px 0 0 16px; padding: 0; }
    li { margin-bottom: 1px; }
    p { margin: 0; }
  </style></head><body>
    <h1>${esc(per.full_name)}</h1>
    <div class="headline">${esc(ai.headline || per.headline[lang])}</div>
    <div class="contact">${esc(per.location)} · ${esc(per.phone)} · ${esc(per.email)} ·
      <a href="${esc(per.linkedin)}">LinkedIn</a> · <a href="${esc(per.github)}">GitHub</a></div>
    <h2>${T.summary}</h2><p>${esc(summary)}</p>
    <h2>${T.projects}</h2>
    ${projects.map(({ src, bullets }) => `<div class="proj">
      <div class="proj-title">${src.url ? `<a href="${esc(src.url)}">${esc(src.name[lang])}</a>` : esc(src.name[lang])}
        <span class="stack"> — ${esc(src.stack.join(', '))}${src.org ? ' · ' + esc(src.org) : ''}${src.dates ? ' · ' + esc(src.dates) : ''}</span></div>
      <ul>${bullets.map(b => `<li>${esc(b)}</li>`).join('')}</ul></div>`).join('')}
    <h2>${T.skills}</h2>
    <ul>${groupOrder.map(g => `<li><b>${T.groups[g] || g}:</b> ${esc(groups[g].join(', '))}</li>`).join('')}</ul>
    <h2>${T.education}</h2>
    <ul>${P.education.map(e => `<li><b>${esc(e.title[lang])}</b> — ${esc(e.institution)}${e.location ? ', ' + esc(e.location) : ''} · ${esc(e.dates)}</li>`).join('')}</ul>
    <h2>${T.languages}</h2><p>${T.langs}</p>
  </body></html>`;

  const slug = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 40);
  const file_name = `${req.job_id}_${slug(req.company)}_${lang}.pdf`;

  out.push({
    json: {
      job_id: req.job_id, file_name, cover_letter: cover,
      tailored: { lang, headline: ai.headline, summary, skills_order: ordered.map(s => s.name),
                  projects: projects.map(p => ({ id: p.src.id, bullets: p.bullets })), checks },
    },
    binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html' } },
    pairedItem: { item: i },
  });
});

return out;
